'use strict';
const {motifs,counts,cells}=window.ATLAS;
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const imageURL=v=>(window.MOTIF_LOGOS||{})[v]||v;
const fmt=v=>Number(v).toLocaleString('en-US'),score=v=>v==null||v===''?'—':Number(v).toFixed(3);
$('#nInstances').textContent=(motifs.reduce((s,m)=>s+m.total_instances,0)/1e6).toFixed(1)+'M';$('#nCells').textContent=new Set(cells.map(c=>c.subtype)).size;
[...new Set(motifs.map(m=>m.category))].sort().forEach(c=>$('#category').add(new Option(c,c)));
const columns=[['annotation3','Motif'],['logo (fwd)','Forward CWM'],['logo (rev)','Reverse CWM'],['category','Category'],['posneg','Class'],['total_instances','Instances'],['n_subtypes','Subtypes'],['num_seqlets','Seqlets'],['num_motifs','Components'],['motif_string','Consensus'],['reference_name0','Reference match'],['reference_score0','Reference score'],['hdma_name0','HDMA match'],['hdma_score0','HDMA score']];
let sort='total_instances',asc=false,page=0,filtered=[];
columns.forEach(([key,label])=>{let th=document.createElement('th'),b=document.createElement('button');b.textContent=label;b.dataset.key=key;b.addEventListener('click',()=>{asc=sort===key?!asc:true;sort=key;page=0;render()});th.append(b);$('#head').append(th)});
function render(){let q=$('#search').value.toLowerCase().trim();filtered=motifs.filter(m=>(!$('#category').value||m.category===$('#category').value)&&(!$('#sign').value||m.posneg===$('#sign').value)&&(!q||Object.entries(m).filter(([k,v])=>!k.includes('logo')).some(([k,v])=>String(v).toLowerCase().includes(q))));filtered.sort((a,b)=>{let x=a[sort],y=b[sort];return (typeof x==='number'&&typeof y==='number'?x-y:String(x??'').localeCompare(String(y??''),undefined,{numeric:true}))*(asc?1:-1)});const n=+$('#size').value;page=Math.min(page,Math.max(0,Math.ceil(filtered.length/n)-1));$('#body').innerHTML=filtered.slice(page*n,(page+1)*n).map(m=>'<tr>'+columns.map(([k])=>{let v=m[k];if(k.includes('logo'))return `<td><img loading="lazy" src="${esc(imageURL(v))}" alt="${esc(m.annotation3)} ${esc(k)}"></td>`;if(k==='annotation3')return `<td><button class="id" data-id="${esc(v)}">${esc(v)}</button><small>${esc(m.annotation)}</small></td>`;if(k==='category'||k==='posneg')return `<td><span class="badge ${v==='neg'?'neg':''}">${esc(v)}</span></td>`;if(typeof v==='number')return `<td class="num">${k.includes('score')?score(v):fmt(v)}</td>`;return `<td>${esc(v||'—')}</td>`}).join('')+'</tr>').join('')||'<tr><td colspan="14">No motifs match these filters.</td></tr>';$('#result').textContent=`${fmt(filtered.length)} of ${motifs.length} motifs`;$('#pageInfo').textContent=filtered.length?`${page*n+1}–${Math.min((page+1)*n,filtered.length)} of ${filtered.length}`:'0 results';$('#prev').disabled=page===0;$('#next').disabled=(page+1)*n>=filtered.length;$('#head').querySelectorAll('th').forEach((th,i)=>{const k=columns[i][0];th.setAttribute('aria-sort',k===sort?(asc?'ascending':'descending'):'none');th.firstChild.textContent=columns[i][1]+(k===sort?(asc?' ↑':' ↓'):'')})}
['search','category','sign','size'].forEach(id=>$('#'+id).addEventListener(id==='search'?'input':'change',()=>{page=0;render()}));$('#reset').onclick=()=>{['search','category','sign'].forEach(id=>$('#'+id).value='');page=0;sort='total_instances';asc=false;render()};$('#prev').onclick=()=>{page--;render()};$('#next').onclick=()=>{page++;render()};
$('#export').onclick=()=>{let cols=columns.filter(([k])=>!k.includes('logo'));const clean=v=>String(v??'').replace(/[\t\r\n]/g,' ');let data=[cols.map(([k])=>k).join('\t'),...filtered.map(m=>cols.map(([k])=>clean(m[k])).join('\t'))].join('\n');let url=URL.createObjectURL(new Blob([data],{type:'text/tab-separated-values;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='motif_selection.tsv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
function renderCells(){let q=$('#cellSearch').value.toLowerCase();$('#cellBody').innerHTML=cells.filter(c=>(c.majortype+' '+c.subtype).toLowerCase().includes(q)).map(c=>`<tr><td>${esc(c.majortype)}</td><td>${esc(c.subtype)}</td><td><span class="badge ${c.pattern_class==='neg_patterns'?'neg':''}">${esc(c.pattern_class)}</span></td>${['total_instances','median_instances_per_hit_peak','n_peaks_with_instances','n_input_peaks'].map(k=>`<td class="num">${fmt(c[k])}</td>`).join('')}<td class="num">${(Number(c.proportion_peaks)*100).toFixed(2)}%</td></tr>`).join('')||'<tr><td colspan="8">No matching cell types.</td></tr>'}$('#cellSearch').oninput=renderCells;
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{document.querySelectorAll('nav button').forEach(t=>t.classList.toggle('active',t===b));['motifs','cells','about'].forEach(id=>$('#'+id).hidden=id!==b.dataset.view)});
let active;
function distribution(){let rows=counts.filter(c=>c.motif_name===active.annotation3&&(!$('#detailSign').value||c.pattern_class===$('#detailSign').value)).sort((a,b)=>b.count-a.count),max=Math.max(1,...rows.map(r=>r.count));$('#distribution').innerHTML=rows.map(r=>`<tr><td>${esc(r.subtype)}</td><td>${esc(r.majortype)}</td><td>${esc(r.pattern_class)}</td><td class="num">${fmt(r.count)}<div class="bar"><i style="width:${r.count/max*100}%"></i></div></td></tr>`).join('')||'<tr><td colspan="4">No supplied instance records for this class.</td></tr>'}
function detail(id){active=motifs.find(m=>m.annotation3===id);if(!active)return;let m=active;$('#detailContent').innerHTML=`<p class="eyebrow">CONSENSUS MOTIF</p><h2>${esc(m.annotation3)}</h2><div class="logos">${['logo (fwd)','logo (rev)'].map(k=>`<figure><img src="${esc(imageURL(m[k]))}" alt="${esc(k)}"><figcaption>${esc(k)}</figcaption></figure>`).join('')}</div><dl>${[['Category',m.category],['Consensus',m.motif_string],['Instances',fmt(m.total_instances)],['Subtypes with records',m.n_subtypes],['Original name',m.name],['Reference match',m.reference_name0+' · score '+score(m.reference_score0)],['HDMA match',m.hdma_name0+' · score '+score(m.hdma_score0)],['Mean distance from summit',score(m.avg_dist_from_summit)],['Manual notes',m.manual_notes||'—']].map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v)}</dd>`).join('')}</dl><h3>Instances by cell subtype</h3><select id="detailSign" aria-label="Filter instance pattern class"><option value="">All pattern classes</option><option>pos_patterns</option><option>neg_patterns</option></select><div class="table-wrap"><table><thead><tr><th>Subtype</th><th>Major type</th><th>Class</th><th>Instances</th></tr></thead><tbody id="distribution"></tbody></table></div>`;$('#detailSign').onchange=distribution;distribution();$('#detail').showModal()}
$('#body').onclick=e=>{let b=e.target.closest('[data-id]');if(b)detail(b.dataset.id)};$('#detail .close').onclick=()=>$('#detail').close();$('#detail').onclick=e=>{if(e.target===$('#detail')){let r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}};
render();renderCells();
